import {validateCourse, freshProgress, safeProgress, normalize, accepts, shuffle, localDay, streak, finishSession, cardKey} from './lib.js';
const $ = (s) => document.querySelector(s);
const esc = (v) => String(v ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const REPO = 'https://github.com/smichea/tara';
const KEY = 'tara-progress-v1', CUSTOM = 'tara-courses-v1', DRAFT = 'tara-draft-v1';
const icons={learn:'<path d="m3 5 9-3 9 3v14l-9 3-9-3zM12 2v20M3 5l9 3 9-3"/>',review:'<path d="M3 11a9 9 0 1 1 2 7M3 4v7h7"/>',words:'<rect x="4" y="3" width="16" height="18" rx="3"/><path d="M8 8h8M8 12h8M8 16h5"/>',community:'<circle cx="9" cy="7" r="3"/><path d="M3 21v-4a6 6 0 0 1 12 0v4M16 4a3 3 0 0 1 0 6M17 13a5 5 0 0 1 4 5v3"/>',settings:'<circle cx="12" cy="12" r="3"/><path d="m9 3-1 3-3 1-2 4 2 3v4l4 3 3-1 3 1 4-3v-4l2-3-2-4-3-1-1-3z"/>',arrow:'<path d="M5 12h14m-6-6 6 6-6 6"/>',check:'<path d="m5 12 4 4L19 6"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',sound:'<path d="m11 4-6 5H2v6h3l6 5zM15 8a6 6 0 0 1 0 8M18 5a10 10 0 0 1 0 14"/>',flame:'<path d="M13 2c2 8-6 7-3 13 2-1 3-3 4-5 8 7 5 12-2 12C1 22 1 10 7 7c0 4 2 4 2 4 3-3 4-5 4-9z"/>',star:'<path d="m12 2 3 6 7 1-5 5 1 8-6-4-6 4 1-8-5-5 7-1z"/>',code:'<path d="m8 6-6 6 6 6m8-12 6 6-6 6M14 3l-4 18"/>',plus:'<path d="M12 4v16M4 12h16"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>',globe:'<circle cx="12" cy="12" r="10"/><ellipse cx="12" cy="12" rx="4" ry="10"/><path d="M2 12h20"/>'};
const icon = (id) => `<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">${icons[id]||icons.star}</svg>`;
let courses=[], custom=[], course, progress=freshProgress(), session=null, result=null, route='learn', draft=null, storageFailed=false;
let toastTimer, voices=[];
function read(key,fallback){try{const raw=localStorage.getItem(key);return raw?JSON.parse(raw):fallback;}catch{return fallback;}}
function persist(key,value){try{localStorage.setItem(key,JSON.stringify(value));return true;}catch{storageFailed=true;toast('Storage is unavailable. Export a backup to keep your work.');return false;}}
function save(){persist(KEY,progress);}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),4500);}
function confirmAction(title,message,action){const d=$('#dialog');d.innerHTML=`<h2>${esc(title)}</h2><p>${esc(message)}</p><form method="dialog" class="actions"><button class="btn secondary" value="cancel">Cancel</button><button class="btn" value="confirm">Continue</button></form>`;d.showModal();d.onclose=()=>{if(d.returnValue==='confirm')action();};}
function allEntries(){return course.lessons.flatMap(l=>l.entries.map(e=>({...e,lessonTitle:l.title})));}
function learned(){return allEntries().filter(e=>progress.cards[cardKey(course,e)]);}
function due(){return learned().filter(e=>progress.cards[cardKey(course,e)].due<=Date.now());}
function completed(l){return !!progress.lessons[`${course.id}:${l.id}`];}
function nextLesson(){return course.lessons.find(l=>!completed(l))||course.lessons[0];}
function nextRoute(r){if(session){confirmAction('Leave this lesson?','Your completed lessons are saved. This unfinished session will be lost.',()=>{session=null;result=null;location.hash=r;render();});return;}location.hash=r;if(route===r)render();}
function speak(entry){
  if(entry.audio){const a=new Audio(new URL(entry.audio,document.baseURI).href);a.play().catch(()=>toast('This recording could not be played.'));return;}
  const code=course.languageCode.toLowerCase();
  const voice=voices.find(v=>v.lang.toLowerCase().split('-')[0]===code.split('-')[0]||(['fil','tl'].includes(code)&&/^(fil|tl)(-|$)/i.test(v.lang)));
  if(!voice){toast(`No ${course.language} voice is installed. Reading practice is still available.`);return;}
  speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(entry.text);u.voice=voice;u.lang=voice.lang;u.rate=.85;speechSynthesis.speak(u);
}
function canSpeak(entry){return !!entry.audio||voices.some(v=>v.lang.toLowerCase().split('-')[0]===course.languageCode.toLowerCase().split('-')[0]||(['fil','tl'].includes(course.languageCode)&&/^(fil|tl)(-|$)/i.test(v.lang)));}
function audioButton(entry){return `<button class="audio-btn" data-action="audio" data-id="${esc(entry.id)}" aria-label="Listen to ${esc(entry.text)}" ${canSpeak(entry)?'':`disabled title="No ${esc(course.language)} voice installed"`}>${icon('sound')}</button>`;}
function illustration(){return `<svg class="hero-art" viewBox="0 0 330 270" preserveAspectRatio="xMidYMax slice" aria-hidden="true"><circle cx="223" cy="84" r="44" fill="#e9cf72"/><path d="M-20 255 105 98 240 270" fill="#296c4d"/><path d="m70 270 151-146 150 146" fill="#43825a"/><path d="m130 270 130-93 120 93" fill="#8eaa67"/><path d="M176 256q8-65 0-139" stroke="#d1b66c" stroke-width="7" fill="none"/><g fill="#b2cb7b"><path d="M179 120q-48-62-89-21 50-8 89 21"/><path d="M178 120q-11-76 33-82-22 34-33 82"/><path d="M180 121q44-53 88-15-49-4-88 15"/><path d="M179 119q29-18 60 21-36-9-60-21"/><path d="M178 120q-42-21-62 20 30-15 62-20"/></g><path d="M3 264q100-39 210 0" stroke="#d0d99a" stroke-width="4" fill="none"/><g fill="#e9cf72"><path d="m72 57 2-8 3 8 8 2-8 3-3 8-2-8-8-3z"/><circle cx="291" cy="50" r="3"/><circle cx="100" cy="35" r="2"/></g></svg>`;}
function shell(body){
 const nav=[['learn','Learn'],['review','Review'],['words','Phrasebook'],['community','Community'],['settings','Settings']];
 return `<div class="shell"><aside class="sidebar"><a class="brand" href="#learn" aria-label="Tara home">tara<span>!</span></a><p class="brand-caption">Language. Together.</p><nav class="nav" aria-label="Main navigation">${nav.map(([id,title])=>`<a href="#${id}" ${route===id?'class="active" aria-current="page"':''}>${icon(id)}${title}</a>`).join('')}</nav><div class="side-bottom"><a class="open-badge" href="${REPO}" target="_blank" rel="noopener">${icon('code')} Open source. Open to you.</a><p>Built by people.<br>For real conversations.<br>Free, without the ads.</p></div></aside><div class="workspace"><header class="topbar"><div class="actions"><span class="brand mobile-brand">t<span>!</span></span><label class="sr-only" for="course-select">Choose a language course</label><select id="course-select" class="course-select">${[...courses,...custom].map(c=>`<option value="${esc(c.id)}" ${c.id===course.id?'selected':''}>${esc(c.language)} · from ${esc(c.fromLanguage)}${custom.includes(c)?' (local)':''}</option>`).join('')}</select></div><div class="stats"><span class="stat" title="Days in a row">${icon('flame')}${streak(progress.activity)} <span class="desktop-label">day${streak(progress.activity)===1?'':'s'}</span></span><span class="stat">${icon('star')}${progress.xp} XP</span><span class="avatar" title="Your learning, on this device">M</span></div></header><main id="main" class="content" tabindex="-1">${storageFailed?'<div class="warning">Browser storage is unavailable. Export your progress before closing this page.</div>':''}${body}</main></div></div>`;
}
function intro(eyebrow,title,text,right=''){return `<div class="page-intro"><div><p class="eyebrow">${eyebrow}</p><h1>${title}</h1><p>${text}</p></div>${right}</div>`;}
function home(){
 const next=nextLesson(), count=course.lessons.filter(completed).length, goal=!!progress.activity[localDay()];
 const groups=['Find your words','Everyday life','Make it yours'];
 return intro('A little every day','Your next conversation starts here.',`A few minutes of ${esc(course.language)}. A little more confidence.`,`<span class="pill green">${icon('globe')} ${esc(course.fromLanguage)} → ${esc(course.language)}</span>`)+
 `<section class="hero"><div class="hero-copy"><p class="eyebrow">${count===course.lessons.length?'Keep your momentum':'Your next small step'}</p><h2>${esc(next.title)}<br><span style="color:#c9dfa7">You’ve got this.</span></h2><p>${esc(next.goal)}</p><button class="btn lime" data-action="start" data-id="${esc(next.id)}">${count===course.lessons.length?'Practise again':'Let’s do this'} ${icon('arrow')}</button></div>${illustration()}</section><div class="dashboard"><section aria-label="Lesson path"><div class="section-head"><h2>Your learning path</h2><span class="tiny">${count} / ${course.lessons.length} complete</span></div><div class="lessons">${course.lessons.map((l,i)=>`${i%4===0?`<div class="unit-heading"><span>UNIT ${Math.floor(i/4)+1}</span><h3>${course.id==='fil-en'?groups[Math.floor(i/4)]||'Keep going':'Keep exploring'}</h3></div>`:''}<button class="lesson ${completed(l)?'done':next.id===l.id?'current':''}" data-action="start" data-id="${esc(l.id)}"><span class="lesson-number">${completed(l)?icon('check'):String(i+1).padStart(2,'0')}</span><span class="lesson-text"><h3>${esc(l.title)}</h3><p>${esc(l.goal)}</p></span>${icon('arrow')}</button>`).join('')}</div><p class="footer-note">Every lesson is available. No hearts, no waiting.<br>${course.status==='draft'?'This starter course is a draft awaiting fluent-speaker review.':''}</p></section><aside class="dashboard-aside"><section class="side-card"><h3>A small daily win</h3><div class="goal-ring-row"><div class="goal-ring ${goal?'done':''}">${goal?icon('check'):'0/1'}</div><div><strong>${goal?'You showed up!':'One short session'}</strong><p>${goal?'Your daily goal is complete.':'That’s all it takes to start.'}</p></div></div><div class="week">${Array.from({length:7},(_,i)=>{const d=new Date();d.setDate(d.getDate()-6+i);return `<div class="day">${d.toLocaleDateString('en',{weekday:'narrow'})}<i class="${progress.activity[localDay(d)]?'on':''}">${progress.activity[localDay(d)]?'✓':'·'}</i></div>`;}).join('')}</div></section><section class="side-card warm"><div class="real-world">↗</div><h3>Take it into the real world</h3><p>Try one new phrase with a friend today. It doesn’t have to be perfect.</p><span class="pill">Small steps count.</span></section><section class="side-card"><h3>A language belongs to everyone.</h3><p>Know a better way to say it? Help the next learner find their words.</p><a href="#community" class="text-link">Meet the community ${icon('arrow')}</a></section></aside></div>`;
}
function reviewPage(){const learnedCount=learned().length,dueCount=due().length;return intro('Make it stick','A little recall goes a long way.','Review what you’ve learned, with more time for the tricky bits.')+`<div class="grid"><section class="card"><span class="community-mark">↻</span><h2>${dueCount} ${dueCount===1?'phrase is':'phrases are'} ready</h2><p>Review dates adapt to your answers. A phrase you miss returns sooner; a familiar one gets more space.</p><button class="btn" data-action="review" ${dueCount?'':'disabled'}>Review due phrases ${icon('arrow')}</button></section><section class="card"><span class="community-mark">✦</span><h2>${learnedCount} words & phrases learned</h2><p>${learnedCount?'Want a little extra practice? Revisit up to eight familiar phrases at a time.':'Finish a lesson to start your personal review collection.'}</p><button class="btn secondary" data-action="practice" ${learnedCount?'':'disabled'}>Practise learned phrases</button></section></div><p class="footer-note">An incorrect answer is scheduled again in 10 minutes. Correct answers return after 1, 3, 7, 14, 30 and 60 days.<br>Your progress is stored in this browser. Use Settings to export a backup.</p>`;}
function wordsPage(){return intro('Words you can use','Your pocket phrasebook.','Find a phrase, check its meaning, then try it out.')+`<label class="sr-only" for="word-search">Search words and translations</label><input id="word-search" class="search" type="search" placeholder="Search ${esc(course.language)} or ${esc(course.fromLanguage)}…"><div class="note">${canSpeak(allEntries()[0])?'Audio uses an available recording or a voice installed on your device.':'No matching voice is installed on this device. Audio buttons will become available if you install a Filipino voice, or contributors add recordings.'}</div><div id="word-list">${wordRows(allEntries())}</div>`;}
function wordRows(entries){return entries.length?entries.map(e=>`<article class="word-row"><div><h3>${esc(e.text)}</h3><p class="muted">${esc(e.translation)}</p><small>${esc(e.lessonTitle)} ${progress.cards[cardKey(course,e)]?'· learned':''}</small></div>${audioButton(e)}</article>`).join(''):'<p class="empty">No phrases match your search.</p>';}
function communityPage(){return intro('Language. Together.','Build something worth sharing.','Add a word. Improve a phrase. Open the door to another language.')+`<div class="grid"><section class="card"><span class="community-mark">＋</span><h2>You know a phrase. Someone needs it.</h2><p>Use the editor to create a lesson, improve the current course, or start a new language. Try your draft locally, then propose it for community review.</p><div class="actions"><button class="btn" data-action="new-draft">Create a course ${icon('plus')}</button><button class="btn secondary" data-action="fork-draft">Improve this course</button></div>${read(DRAFT,null)?'<p><button class="btn ghost small" data-action="resume-draft">Resume saved draft</button></p>':''}</section><section class="card"><span class="community-mark">↗</span><h2>Open from the first word.</h2><p>The app is MIT licensed. Course content is CC BY-SA 4.0: anyone can reuse and improve it with attribution and the same content license.</p><a class="btn secondary" href="${REPO}" target="_blank" rel="noopener">Explore the source ${icon('code')}</a></section></div><section class="card" style="margin-top:20px"><h2>How a contribution becomes a lesson</h2><div class="grid"><div><p class="step">01 · Create & try</p><p>Add words, phrases, translations, notes and accepted answers. Test your course on your device before sharing it.</p><p class="step">02 · Propose</p><p>The editor prepares a GitHub contribution proposal. A GitHub account is needed to submit; no coding is required.</p></div><div><p class="step">03 · Review & publish</p><p>Automated checks validate the file. A fluent speaker checks meaning, natural usage and examples. Maintainers merge approved lessons into the shared course.</p><p class="step">04 · Another language</p><p>The same open course format supports new language pairs. Add a course file and register it, without changing the learning engine.</p></div></div></section><section class="card" style="margin-top:20px"><div class="section-head"><h2>Courses on this device</h2><button class="btn ghost small" data-action="import-course">Import course ${icon('plus')}</button></div>${[...courses,...custom].map(c=>`<div class="course-item"><div><h3>${esc(c.title)}</h3><p>${esc(c.fromLanguage)} → ${esc(c.language)} · ${c.lessons.length} lessons · ${custom.includes(c)?'local draft':c.status==='reviewed'?'reviewed':'awaiting fluent-speaker review'}</p><p>By ${esc(c.author)}${c.derivedFrom?` · based on ${esc(c.derivedFrom.author)}`:''} · CC BY-SA 4.0</p></div>${custom.includes(c)?`<button class="btn ghost small" data-action="remove-course" data-id="${esc(c.id)}">Remove</button>`:'<span class="pill">Starter course</span>'}</div>`).join('')}</section><p class="footer-note">Imported drafts stay on your device. Shared course changes go through review on GitHub.<br>Native-speaker recordings can be contributed under the same content license. Drafts do not automatically become reviewed courses.</p>`;}
function settingsPage(){return intro('Your learning, your way','Keep your progress close.','No account for lessons. No ads. No paid features.')+`<div class="grid"><section class="card"><h2>Progress & backups</h2><p>Your XP, lesson results and review dates live in this browser. Export them before changing devices or clearing browser data.</p><div class="actions"><button class="btn" data-action="export-progress">Export backup ${icon('download')}</button><button class="btn secondary" data-action="import-progress">Restore backup</button></div><p class="field-help">Backups also include imported local courses. Drafts from the editor must be exported separately.</p></section><section class="card"><h2>On your home screen</h2><p>In your browser menu, choose “Install app” or “Add to Home Screen” when available. The app works offline after its first complete load.</p><p class="field-help">There is no cloud sync. Progress belongs to this browser and device.</p></section><section class="card"><h2>Sound & pronunciation</h2><p>${canSpeak(allEntries()[0])?'A matching voice or recording is available. Tap a speaker button to listen.':'No matching system voice is available. Install a Filipino voice in your device’s speech settings, or use the reading exercises.'}</p><p class="field-help">System-generated speech is a practice aid. Community recordings are supported; the starter course does not yet include human recordings. The app never substitutes an English voice.</p></section><section class="card"><h2>A fresh start</h2><p>Reset completed lessons, XP and review dates. Export a backup first if you want to keep them.</p><button class="btn ghost" data-action="reset">Reset learning progress</button></section></div><section class="note" style="margin-top:20px">Tara! v0.1 · A community-built starting point. Course examples are drafts pending fluent-speaker review. This app contains no advertising, analytics scripts or external AI services. Your device’s speech service may use an online voice, depending on your system settings. <a href="${REPO}/blob/main/PRIVACY.md" target="_blank" rel="noopener">Privacy details</a>.</section>`;}
function render(){
 if(!course)return;
 route=location.hash.slice(1)||'learn';
 if(session){renderSession();return;}
 if(result){renderResult();return;}
 const pages={learn:home,review:reviewPage,words:wordsPage,community:communityPage,settings:settingsPage,editor:editorPage};
 if(!pages[route])route='learn';
 $('#app').innerHTML=shell(pages[route]());
 $('#course-select').addEventListener('change',e=>{course=[...courses,...custom].find(c=>c.id===e.target.value);persist('tara-selected',course.id);render();});
 if(route==='words')$('#word-search').addEventListener('input',e=>{$('#word-list').innerHTML=wordRows(allEntries().filter(x=>normalize(`${x.text} ${x.translation}`).includes(normalize(e.target.value))));});
 if(route==='editor')$('#course-editor').addEventListener('input',()=>{captureDraft();persist(DRAFT,draft);$('#draft-status').textContent='Draft saved on this device';});
}
function startLesson(id){const lesson=course.lessons.find(l=>l.id===id);if(!lesson)return;result=null;session={lesson,entries:lesson.entries,phase:'learn',index:0,queue:shuffle(lesson.entries.flatMap(entry=>[{entry,type:'choice',retried:false},{entry,type:entry.text.trim().split(/\s+/).length>1?'build':'type',retried:false}])),answers:[],selected:null,checked:false,tokens:[],chosen:[]};renderSession();window.scrollTo(0,0);}
function startReview(all=false){const entries=shuffle(all?learned():due()).slice(0,8);if(!entries.length)return;result=null;session={lesson:{id:'review',title:'A little recall'},entries,phase:'exercise',index:0,queue:entries.map(entry=>({entry,type:entry.text.trim().split(/\s+/).length>1?'build':'type',retried:false})),answers:[],selected:null,checked:false,tokens:[],chosen:[]};prepareQuestion();renderSession();window.scrollTo(0,0);}
function prepareQuestion(){const q=session.queue[session.index];session.selected=null;session.checked=false;session.input='';session.chosen=[];session.tokens=shuffle(q.entry.text.trim().split(/\s+/).map((text,i)=>({text,id:i})));const seen=new Set([normalize(q.entry.translation)]);const other=shuffle(allEntries()).filter(e=>{const v=normalize(e.translation);if(seen.has(v))return false;seen.add(v);return true;}).slice(0,3);session.options=shuffle([q.entry,...other]);}
function renderSession(){
 const s=session,teaching=s.phase==='learn',entry=teaching?s.entries[s.index]:s.queue[s.index].entry;
 const total=s.entries.length+s.queue.length, done=teaching?s.index:s.entries.length+s.index;
 let body='';
 if(teaching){body=`<p class="eyebrow">${esc(s.lesson.title)} · Make it familiar</p><h1 class="session-title">A phrase for your next conversation.</h1><div class="study-card"><span class="pill green">${esc(entry.kind)} · ${esc(course.language)}</span><h2 class="study-text" dir="auto">${esc(entry.text)}</h2>${audioButton(entry)}<p class="study-translation">${esc(entry.translation)}</p><p class="study-note">${esc(entry.note||'Read it once, then try saying it aloud.')}</p></div>${s.index===0&&s.lesson.tip?`<div class="note">${esc(s.lesson.tip)}</div>`:''}<div class="session-bottom"><p>${s.index+1} of ${s.entries.length} new phrases</p><button class="btn" data-action="learn-next">${s.index===s.entries.length-1?'Let’s practise':'Got it'} ${icon('arrow')}</button></div>`;}
 else{const q=s.queue[s.index];body=`<p class="eyebrow">${esc(s.lesson.title)} ${q.retried?'· One more try':''}</p><h1 class="session-title">${q.type==='choice'?'What does this mean?':q.type==='build'?'Build the phrase.':'Write it in '+esc(course.language)+'.'}</h1><div class="question-prompt" dir="auto">${esc(q.type==='choice'?entry.text:entry.translation)}</div>`;
 if(q.type==='choice'){body+=`<div class="choices">${s.options.map((o,i)=>`<button class="choice ${s.selected===o.id?'selected':''} ${s.checked&&o.id===entry.id?'correct':''} ${s.checked&&s.selected===o.id&&o.id!==entry.id?'wrong':''}" data-action="choice" data-id="${esc(o.id)}" ${s.checked?'disabled':''}><span class="key">${i+1}</span>${esc(o.translation)}</button>`).join('')}</div>`;}
 if(q.type==='build'){body+=`<p class="tiny">Tap the words in order. Tap a chosen word to put it back.</p><div class="token-answer" aria-label="Your answer">${s.chosen.map(id=>{const t=s.tokens.find(x=>x.id===id);return `<button class="token" data-action="untoken" data-index="${id}" ${s.checked?'disabled':''}>${esc(t.text)}</button>`;}).join('')}${!s.chosen.length?'<span class="tiny">Your phrase goes here…</span>':''}</div><div class="token-bank">${s.tokens.map(t=>`<button class="token" data-action="token" data-index="${t.id}" ${s.chosen.includes(t.id)||s.checked?'disabled':''}>${esc(t.text)}</button>`).join('')}</div>`;}
 if(q.type==='type'){body+=`<label class="sr-only" for="answer-input">Your answer in ${esc(course.language)}</label><input class="answer-input" id="answer-input" autocomplete="off" autocapitalize="none" spellcheck="false" placeholder="Type your answer…" value="${esc(s.input)}" ${s.checked?'disabled':''}>`;}
 if(s.checked)body+=`<div class="feedback ${s.correct?'':'bad'}" role="status"><h3>${s.correct?'Nice work!':'You’re learning. Try it this way:'}</h3><p>${s.correct?'':`<strong>${esc(entry.text)}</strong> · ${esc(entry.translation)}<br>`}${esc(entry.note||'You’ll see this phrase again in your reviews.')}</p></div>`;
 const ready=q.type==='choice'?!!s.selected:q.type==='build'?s.chosen.length>0:!!s.input?.trim();
 body+=`<div class="session-bottom"><p>${s.checked?(s.correct?'A little more confident.':'Mistakes help us learn.'):'Take your time. No hearts to lose.'}</p><button class="btn" id="check-answer" data-action="${s.checked?'exercise-next':'check'}" ${!s.checked&&!ready?'disabled':''}>${s.checked?'Continue':'Check answer'} ${icon('arrow')}</button></div>`;}
 $('#app').innerHTML=`<main class="session-shell"><div class="session-top"><button class="icon-btn" data-action="leave" aria-label="Leave lesson">${icon('close')}</button><div class="progress-track" role="progressbar" aria-label="Lesson progress" aria-valuemin="0" aria-valuemax="${total}" aria-valuenow="${done}"><div class="progress-fill" style="width:${Math.round(done/total*100)}%"></div></div><span class="session-counter">${teaching?'Learn':'Practise'}</span></div>${body}</main>`;
 if($('#answer-input')){$('#answer-input').addEventListener('input',e=>{session.input=e.target.value;$('#check-answer').disabled=!session.input.trim();});}
}
function checkAnswer(){const s=session;if(!s||s.checked)return;const q=s.queue[s.index];const text=q.type==='choice'?s.selected:q.type==='build'?s.chosen.map(id=>s.tokens.find(t=>t.id===id).text).join(' '):s.input;s.correct=q.type==='choice'?s.selected===q.entry.id:accepts(text,q.entry);s.checked=true;s.answers.push({entry:q.entry,correct:s.correct});if(!s.correct&&!q.retried)s.queue.push({...q,retried:true});renderSession();$('#check-answer')?.focus();}
function finish(){const s=session;const outcome=finishSession(progress,course,s.lesson.id,s.answers);progress=outcome.progress;save();result={...outcome,title:s.lesson.title,review:s.lesson.id==='review',entries:s.entries};session=null;renderResult();window.scrollTo(0,0);}
function renderResult(){const r=result;$('#app').innerHTML=`<main class="session-shell"><div class="result"><div class="result-symbol">✦</div><p class="eyebrow">You showed up. That matters.</p><h1>${r.review?'A little stronger.':'One conversation closer.'}</h1><p class="muted">${esc(r.title)} · Session complete</p><div class="result-stats"><div><strong>+${r.xp}</strong><span>XP earned</span></div><div><strong>${r.accuracy}%</strong><span>Correct attempts</span></div><div><strong>${streak(progress.activity)}</strong><span>Day streak</span></div></div><div class="note">Try this in real life today:<br><strong>${esc(r.entries[0].text)}</strong> — ${esc(r.entries[0].translation)}</div><p class="footer-note">${r.xp===0?'You already earned XP for this session today. Your reviews are still updated.':'Your progress and review dates are saved on this device.'}</p><button class="btn" data-action="back-path">Back to your path ${icon('arrow')}</button></div></main>`;}
function download(name,value){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(value,null,2)+'\n'],{type:'application/json'}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
function pickFile(callback){const input=document.createElement('input');input.type='file';input.accept='.json,application/json';input.addEventListener('change',async()=>{try{const file=input.files[0];if(!file)return;if(file.size>2000000)throw new Error('Choose a JSON file smaller than 2 MB.');await callback(JSON.parse(await file.text()));}catch(e){toast(e.message||'Could not read this file.');}});input.click();}
function addCourse(value){const errors=validateCourse(value);if(errors.length)throw new Error(errors.slice(0,3).join(' '));const copy=structuredClone(value);copy.status='draft';copy.reviewers=[];if(courses.some(c=>c.id===copy.id))copy.id=`local-${copy.id}`.slice(0,64);const index=custom.findIndex(c=>c.id===copy.id);if(index>=0)custom[index]=copy;else custom.push(copy);if(!persist(CUSTOM,custom))return;course=copy;persist('tara-selected',course.id);nextRoute('learn');toast('Local draft ready to try. It has not been published.');}
function newDraft(fork=false){if(fork){draft=structuredClone(course);draft.status='draft';draft.reviewers=[];draft.derivedFrom={courseId:course.id,author:course.author,license:course.license};draft.author='';}else draft={schemaVersion:1,id:'my-course',title:'',language:'',languageCode:'',fromLanguage:'English',fromCode:'en',author:'',license:'CC-BY-SA-4.0',status:'draft',reviewers:[],lessons:[blankLesson()]};persist(DRAFT,draft);nextRoute('editor');}
function uid(prefix){return `${prefix}-${crypto.randomUUID().slice(0,8)}`;}
function blankEntry(){return {id:uid('phrase'),kind:'phrase',text:'',translation:'',note:''};}
function blankLesson(){return {id:uid('lesson'),title:'',goal:'',tip:'',entries:[blankEntry()]};}
function field(label,name,value,extra=''){return `<div class="field-group"><label for="f-${name}">${label}</label><input id="f-${name}" name="${name}" value="${esc(value)}" ${extra}></div>`;}
function editorPage(){if(!draft){const saved=read(DRAFT,null);draft=saved||{schemaVersion:1,id:'my-course',title:'',language:'',languageCode:'',fromLanguage:'English',fromCode:'en',author:'',license:'CC-BY-SA-4.0',status:'draft',reviewers:[],lessons:[blankLesson()]};}return intro('Made by the community','Give someone their next words.','Create a course, try it locally, then propose it for review.')+`<div class="note">Your draft is saved on this device as you type. Publishing a shared course requires community review. Existing course content keeps its original attribution.</div><form id="course-editor"><section class="card" style="margin-top:20px"><h2>The course</h2><div class="form-grid">${field('Course title','title',draft.title,'maxlength="100" required')}${field('Course id','id',draft.id,'maxlength="64" pattern="[a-z][a-z0-9-]*" required')}${field('Learning language','language',draft.language,'placeholder="e.g. Filipino" maxlength="100" required')}${field('Language code','languageCode',draft.languageCode,'placeholder="e.g. fil, ja, es" maxlength="20" required')}${field('Instruction language','fromLanguage',draft.fromLanguage,'maxlength="100" required')}${field('Instruction language code','fromCode',draft.fromCode,'maxlength="20" required')}${field('Your attribution / contributor name','author',draft.author,'placeholder="A name or public pseudonym" maxlength="100" required')}</div><p class="field-help">The learning engine supports other languages and scripts. Interface navigation is currently in English. Words, translations and lesson explanations come from the course.</p></section>${draft.lessons.map((l,i)=>`<section class="editor-lesson"><div class="section-head"><h2>Lesson ${i+1}</h2><button type="button" class="btn ghost small" data-action="remove-lesson" data-index="${i}" ${draft.lessons.length===1?'disabled':''}>Remove lesson</button></div><div class="form-grid">${field('Lesson title',`l${i}-title`,l.title,'maxlength="100" required')}${field('Practical goal',`l${i}-goal`,l.goal,'placeholder="What can the learner do afterwards?" maxlength="300" required')}</div>${field('A short teaching tip',`l${i}-tip`,l.tip||'','maxlength="1000"')}${l.entries.map((e,j)=>`<div class="editor-entry"><div class="entry-heading"><span>Word or phrase ${j+1}</span><button type="button" class="btn ghost small" data-action="remove-entry" data-lesson="${i}" data-index="${j}" ${l.entries.length===1?'disabled':''}>Remove</button></div><div class="form-grid">${field('Learning-language text',`l${i}e${j}-text`,e.text,'maxlength="300" required')}${field('Meaning / translation',`l${i}e${j}-translation`,e.translation,'maxlength="300" required')}</div><div class="form-grid"><div class="field-group"><label for="kind-${i}-${j}">Entry type</label><select class="field" id="kind-${i}-${j}" name="l${i}e${j}-kind"><option value="phrase" ${e.kind==='phrase'?'selected':''}>Phrase</option><option value="word" ${e.kind==='word'?'selected':''}>Word</option></select></div>${field('Usage note',`l${i}e${j}-note`,e.note||'','maxlength="600"')}</div>${field('Other accepted spellings (separate with |)',`l${i}e${j}-accepted`,(e.accepted||[]).join(' | '),'maxlength="1000"')}</div>`).join('')}<button type="button" class="btn secondary small" data-action="add-entry" data-index="${i}">${icon('plus')} Add a word or phrase</button></section>`).join('')}<button type="button" class="btn secondary" data-action="add-lesson">${icon('plus')} Add a lesson</button><label class="checkbox-label"><input type="checkbox" id="content-license" ${draft.agreed?'checked':''}> <span>I wrote these additions or have permission to share them. I agree to publish my course contributions under <a href="https://creativecommons.org/licenses/by-sa/4.0/" target="_blank" rel="noopener">CC BY-SA 4.0</a>, with attribution. I have not copied a proprietary course.</span></label><div id="editor-errors" role="alert"></div><div class="editor-footer"><div class="actions"><button type="button" class="btn secondary" data-action="try-draft">Try on my device</button><button type="button" class="btn secondary" data-action="export-draft">Export JSON ${icon('download')}</button><button type="button" class="btn" data-action="propose">Propose contribution ${icon('arrow')}</button></div><p id="draft-status" class="saved" style="margin:10px 0 0">Draft stays on this device until you export or submit it.</p></div></form>`;}
function captureDraft(){const f=$('#course-editor');if(!f)return;const data=new FormData(f);for(const key of ['title','id','language','languageCode','fromLanguage','fromCode','author'])draft[key]=String(data.get(key)||'').trim();draft.agreed=$('#content-license').checked;draft.lessons.forEach((l,i)=>{for(const key of ['title','goal','tip'])l[key]=String(data.get(`l${i}-${key}`)||'').trim();l.entries.forEach((e,j)=>{for(const key of ['text','translation','kind','note'])e[key]=String(data.get(`l${i}e${j}-${key}`)||'').trim();e.accepted=String(data.get(`l${i}e${j}-accepted`)||'').split('|').map(s=>s.trim()).filter(Boolean);if(!e.accepted.length)delete e.accepted;});if(!l.tip)delete l.tip;});}
function validDraft(requireLicense=false){captureDraft();const value=structuredClone(draft);delete value.agreed;const errors=validateCourse(value);if(requireLicense&&!draft.agreed)errors.push('Please confirm the content license before sharing.');$('#editor-errors').innerHTML=errors.length?`<div class="errors"><strong>Please check these details:</strong><ul>${errors.map(e=>`<li>${esc(e)}</li>`).join('')}</ul></div>`:'';if(errors.length){$('#editor-errors').scrollIntoView({behavior:'smooth',block:'center'});return null;}return value;}
function propose(){const value=validDraft(true);if(!value)return;download(`${value.id}.json`,value);let body=`## Course contribution\n\n- Language pair: ${value.fromLanguage} → ${value.language}\n- Contributor: ${value.author}\n- [x] I have the right to share these additions under CC BY-SA 4.0.\n- [ ] Fluent-speaker review requested\n\n`;const content=JSON.stringify(value,null,2);if(content.length<4500)body+='```json\n'+content+'\n```';else body+='Please attach the exported JSON file here (GitHub accepts a .json file inside a .zip archive, or paste its contents in a fenced code block).';const a=document.createElement('a');a.href=`${REPO}/issues/new?title=${encodeURIComponent('[Course] '+value.title)}&body=${encodeURIComponent(body)}`;a.target='_blank';a.rel='noopener';a.click();toast('JSON exported. Review and submit your proposal on GitHub.');}
const actions={
 start:b=>startLesson(b.dataset.id),review:()=>startReview(),practice:()=>startReview(true),audio:b=>{const e=allEntries().find(e=>e.id===b.dataset.id);if(e)speak(e);},
 leave:()=>confirmAction('Leave this lesson?','This unfinished session will be lost. Completed lessons are saved.',()=>{session=null;render();}),
 'learn-next':()=>{session.index++;if(session.index>=session.entries.length){session.phase='exercise';session.index=0;prepareQuestion();}renderSession();},
 choice:b=>{session.selected=b.dataset.id;renderSession();},token:b=>{session.chosen.push(Number(b.dataset.index));renderSession();},untoken:b=>{session.chosen=session.chosen.filter(x=>x!==Number(b.dataset.index));renderSession();},check:checkAnswer,
 'exercise-next':()=>{session.index++;if(session.index>=session.queue.length)finish();else{prepareQuestion();renderSession();window.scrollTo(0,0);}},
 'back-path':()=>{result=null;location.hash='learn';render();window.scrollTo(0,0);},
 'export-progress':()=>download('tara-backup-'+localDay()+'.json',{format:'tara-backup',version:1,progress,courses:custom}),
 'import-progress':()=>pickFile(value=>{if(value.format!=='tara-backup'||value.version!==1||!Array.isArray(value.courses)||value.courses.length>100)throw new Error('This is not a Tara backup.');const restored=safeProgress(value.progress);const ids=new Set();for(const c of value.courses){const errors=validateCourse(c);if(errors.length||ids.has(c.id)||courses.some(x=>x.id===c.id))throw new Error('Backup contains an invalid or duplicate course.');ids.add(c.id);}confirmAction('Restore this backup?','This replaces learning progress and imported courses on this device.',()=>{progress=restored;custom=value.courses.map(c=>({...c,status:'draft',reviewers:[]}));save();persist(CUSTOM,custom);if(![...courses,...custom].some(c=>c.id===course.id))course=courses[0];render();toast('Backup restored.');});}),
 reset:()=>confirmAction('Reset your learning progress?','This removes XP, completed lessons and review dates from this device. Imported courses and editor drafts are kept.',()=>{progress=freshProgress();save();render();toast('Learning progress reset.');}),
 'import-course':()=>pickFile(value=>{const errors=validateCourse(value);if(errors.length)throw new Error(errors.slice(0,3).join(' '));confirmAction('Import this course?',`${value.title} (${value.lessons.length} lessons) will be saved as a local, unreviewed draft. An existing local course with the same id will be replaced.`,()=>addCourse(value));}),
 'remove-course':b=>confirmAction('Remove this local course?','This removes the course from this device. Export a copy first to keep your edits.',()=>{custom=custom.filter(c=>c.id!==b.dataset.id);persist(CUSTOM,custom);if(course.id===b.dataset.id)course=courses[0];render();}),
 'new-draft':()=>{if(read(DRAFT,null))confirmAction('Start a new draft?','This replaces the saved editor draft. Export it first if you want to keep it.',()=>newDraft());else newDraft();},
 'fork-draft':()=>{if(read(DRAFT,null))confirmAction('Edit this course?','This replaces the saved editor draft. Export it first if you want to keep it.',()=>newDraft(true));else newDraft(true);},
 'resume-draft':()=>{draft=read(DRAFT,null);nextRoute('editor');},
 'add-lesson':()=>{captureDraft();if(draft.lessons.length>=100){toast('A course can contain up to 100 lessons.');return;}draft.lessons.push(blankLesson());persist(DRAFT,draft);render();},
 'remove-lesson':b=>{captureDraft();draft.lessons.splice(Number(b.dataset.index),1);persist(DRAFT,draft);render();},
 'add-entry':b=>{captureDraft();const l=draft.lessons[Number(b.dataset.index)];if(l.entries.length>=32){toast('A lesson can contain up to 32 entries.');return;}l.entries.push(blankEntry());persist(DRAFT,draft);render();},
 'remove-entry':b=>{captureDraft();draft.lessons[Number(b.dataset.lesson)].entries.splice(Number(b.dataset.index),1);persist(DRAFT,draft);render();},
 'export-draft':()=>{const value=validDraft();if(value)download(`${value.id}.json`,value);},
 'try-draft':()=>{const value=validDraft();if(value){confirmAction('Try this draft?', 'Save this course locally. This replaces a previous local course with the same id; shared courses are kept.',()=>addCourse(value));}},
 propose
};
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(b&&!b.disabled){e.preventDefault();try{actions[b.dataset.action]?.(b);}catch(err){console.error(err);toast('Something went wrong. Your saved progress is still available.');}}});
document.addEventListener('keydown',e=>{if(!session||e.ctrlKey||e.metaKey||e.altKey||$('#dialog').open)return;if(e.key==='Enter'&&(!e.target.matches('button'))){e.preventDefault();if(session.phase==='learn')actions['learn-next']();else if(session.checked)actions['exercise-next']();else if(!$('#check-answer')?.disabled)checkAnswer();}if(session.phase==='exercise'&&!session.checked&&session.queue[session.index].type==='choice'&&/^[1-4]$/.test(e.key)){const option=session.options[Number(e.key)-1];if(option){session.selected=option.id;renderSession();}}});
window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0);});
async function boot(){try{
 const registry=await fetch('./courses/index.json').then(r=>{if(!r.ok)throw new Error('Course list is unavailable.');return r.json();});
 courses=await Promise.all(registry.map(async x=>{if(!/^[a-z0-9-]+\.json$/.test(x.file))throw new Error('Invalid course path.');const response=await fetch('./courses/'+x.file);if(!response.ok)throw new Error('Course unavailable.');const value=await response.json();const errors=validateCourse(value);if(errors.length)throw new Error(errors[0]);return value;}));
 if(!courses.length)throw new Error('No course is available.');
 custom=read(CUSTOM,[]);if(!Array.isArray(custom))custom=[];custom=custom.filter(c=>!validateCourse(c).length&&!courses.some(x=>x.id===c.id)).map(c=>({...c,status:'draft',reviewers:[]}));
 try{progress=safeProgress(read(KEY,freshProgress()));}catch{progress=freshProgress();storageFailed=true;}
 course=[...courses,...custom].find(c=>c.id===read('tara-selected',null))||courses[0];
 if('speechSynthesis'in window){voices=speechSynthesis.getVoices();speechSynthesis.addEventListener('voiceschanged',()=>{voices=speechSynthesis.getVoices();if(!session&&!result&&['words','settings'].includes(route))render();});}
 render();
 if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});
 }catch(e){$('#app').innerHTML=`<main class="boot"><span class="brand">tara<span>!</span></span><h1 style="margin-top:30px">Let’s get you connected.</h1><p>${esc(e.message)} Check your connection and reload.</p><button class="btn" id="reload">Try again</button></main>`;$('#reload').onclick=()=>location.reload();}}
boot();
